-- users schema: companies, users, groups, permissions, scopes, and grants.
-- Apply against open_user_db:
--   sqlcmd -S localhost -U oum -P oum -d open_user_db -C -b -i db/mssql/03_create_schema_users.sql
--
-- Tables users.[user] and users.[grant] are bracketed because USER and GRANT are reserved keywords.
-- All other identifiers are unquoted snake_case. Ids are uniqueidentifier values generated by
-- the application (UUID v7). Unique rules that skip deleted rows use filtered indexes.
-- Soft delete: active + deleted_at on company, user, user_group, permission and scope.
-- Deactivate sets active = 0 and deleted_at. Remove (permanent) is allowed only on a deactivated
-- row with no dependents; it deletes the row and writes a full snapshot to audit_log.
-- Grants and group members are removed outright; the removal is audited.

USE [open_user_db];
GO

SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO

IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = N'users')
BEGIN
  EXEC(N'CREATE SCHEMA users AUTHORIZATION dbo');
END
GO

CREATE TABLE users.company (
  id              uniqueidentifier NOT NULL,
  company_key     nvarchar(50) NOT NULL,
  name            nvarchar(max) NOT NULL,
  email           nvarchar(256) NULL,
  contact_person  nvarchar(max) NULL,
  contact_phone   nvarchar(max) NULL,
  require_mfa     bit NOT NULL CONSTRAINT df_company_require_mfa DEFAULT 0,
  active          bit NOT NULL CONSTRAINT df_company_active DEFAULT 1,
  deleted_at      datetime2 NULL,
  created_at      datetime2 NOT NULL CONSTRAINT df_company_created DEFAULT SYSUTCDATETIME(),
  updated_at      datetime2 NOT NULL CONSTRAINT df_company_updated DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_company PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ux_company_key ON users.company (company_key) WHERE deleted_at IS NULL;
GO

CREATE TABLE users.[user] (
  id             uniqueidentifier NOT NULL,
  company_id     uniqueidentifier NOT NULL,
  user_key       nvarchar(50) NOT NULL,
  username       nvarchar(200) NOT NULL,
  first_name     nvarchar(max) NOT NULL,
  last_name      nvarchar(max) NOT NULL,
  email          nvarchar(256) NULL,
  mobile         nvarchar(25) NULL,
  avatar         varbinary(max) NULL,
  password_hash  nvarchar(max) NOT NULL,
  active         bit NOT NULL CONSTRAINT df_user_active DEFAULT 1,
  deleted_at     datetime2 NULL,
  created_at     datetime2 NOT NULL CONSTRAINT df_user_created DEFAULT SYSUTCDATETIME(),
  updated_at     datetime2 NOT NULL CONSTRAINT df_user_updated DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_user PRIMARY KEY (id),
  CONSTRAINT fk_user_company FOREIGN KEY (company_id) REFERENCES users.company (id)
);
-- SQL Server compares nvarchar case-insensitively with the default collation, so no lower() is needed.
CREATE UNIQUE INDEX ux_user_key ON users.[user] (user_key) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX ux_user_username ON users.[user] (company_id, username) WHERE deleted_at IS NULL;
GO

CREATE TABLE users.user_group (
  id           uniqueidentifier NOT NULL,
  company_id   uniqueidentifier NOT NULL,
  name         nvarchar(200) NOT NULL,
  description  nvarchar(max) NULL,
  avatar       varbinary(max) NULL,
  active       bit NOT NULL CONSTRAINT df_user_group_active DEFAULT 1,
  deleted_at   datetime2 NULL,
  created_at   datetime2 NOT NULL CONSTRAINT df_user_group_created DEFAULT SYSUTCDATETIME(),
  updated_at   datetime2 NOT NULL CONSTRAINT df_user_group_updated DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_user_group PRIMARY KEY (id),
  CONSTRAINT fk_user_group_company FOREIGN KEY (company_id) REFERENCES users.company (id)
);
CREATE UNIQUE INDEX ux_user_group_name ON users.user_group (company_id, name) WHERE deleted_at IS NULL;
GO

CREATE TABLE users.user_group_member (
  user_id   uniqueidentifier NOT NULL,
  group_id  uniqueidentifier NOT NULL,
  CONSTRAINT pk_user_group_member PRIMARY KEY (user_id, group_id),
  CONSTRAINT fk_member_user FOREIGN KEY (user_id) REFERENCES users.[user] (id),
  CONSTRAINT fk_member_group FOREIGN KEY (group_id) REFERENCES users.user_group (id)
);
CREATE INDEX ix_member_group ON users.user_group_member (group_id);
GO

CREATE TABLE users.permission (
  id           uniqueidentifier NOT NULL,
  company_id   uniqueidentifier NOT NULL,
  name         nvarchar(100) NOT NULL,
  description  nvarchar(max) NULL,
  active       bit NOT NULL CONSTRAINT df_permission_active DEFAULT 1,
  deleted_at   datetime2 NULL,
  created_at   datetime2 NOT NULL CONSTRAINT df_permission_created DEFAULT SYSUTCDATETIME(),
  updated_at   datetime2 NOT NULL CONSTRAINT df_permission_updated DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_permission PRIMARY KEY (id),
  CONSTRAINT fk_permission_company FOREIGN KEY (company_id) REFERENCES users.company (id)
);
GO
CREATE UNIQUE INDEX ux_permission_name ON users.permission (company_id, name) WHERE deleted_at IS NULL;
GO

CREATE TABLE users.scope (
  id           uniqueidentifier NOT NULL,
  company_id   uniqueidentifier NOT NULL,
  parent_id    uniqueidentifier NULL,
  scope_key    nvarchar(50) NULL,
  reference    nvarchar(100) NULL,
  name         nvarchar(max) NOT NULL,
  description  nvarchar(max) NULL,
  active       bit NOT NULL CONSTRAINT df_scope_active DEFAULT 1,
  deleted_at   datetime2 NULL,
  created_at   datetime2 NOT NULL CONSTRAINT df_scope_created DEFAULT SYSUTCDATETIME(),
  updated_at   datetime2 NOT NULL CONSTRAINT df_scope_updated DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_scope PRIMARY KEY (id),
  CONSTRAINT fk_scope_company FOREIGN KEY (company_id) REFERENCES users.company (id),
  CONSTRAINT fk_scope_parent FOREIGN KEY (parent_id) REFERENCES users.scope (id),
  CONSTRAINT ck_scope_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE INDEX ix_scope_parent ON users.scope (parent_id);
GO

-- One row gives one permission to a user OR a group, at a scope (NULL = company-wide).
-- subject_id and scope_ref are persisted computed columns so one unique index can cover NULLs.
CREATE TABLE users.[grant] (
  id             uniqueidentifier NOT NULL,
  user_id        uniqueidentifier NULL,
  group_id       uniqueidentifier NULL,
  permission_id  uniqueidentifier NOT NULL,
  scope_id       uniqueidentifier NULL,
  created_at     datetime2 NOT NULL CONSTRAINT df_grant_created DEFAULT SYSUTCDATETIME(),
  created_by     uniqueidentifier NULL,
  subject_id AS (COALESCE(user_id, group_id)) PERSISTED,
  scope_ref AS (COALESCE(scope_id, CAST('00000000-0000-0000-0000-000000000000' AS uniqueidentifier))) PERSISTED,
  CONSTRAINT pk_grant PRIMARY KEY (id),
  CONSTRAINT fk_grant_user FOREIGN KEY (user_id) REFERENCES users.[user] (id),
  CONSTRAINT fk_grant_group FOREIGN KEY (group_id) REFERENCES users.user_group (id),
  CONSTRAINT fk_grant_permission FOREIGN KEY (permission_id) REFERENCES users.permission (id),
  CONSTRAINT fk_grant_scope FOREIGN KEY (scope_id) REFERENCES users.scope (id),
  CONSTRAINT ck_grant_one_subject CHECK ((user_id IS NULL AND group_id IS NOT NULL) OR (user_id IS NOT NULL AND group_id IS NULL))
);
CREATE UNIQUE INDEX ux_grant ON users.[grant] (subject_id, permission_id, scope_ref);
CREATE INDEX ix_grant_user ON users.[grant] (user_id);
CREATE INDEX ix_grant_group ON users.[grant] (group_id);
CREATE INDEX ix_grant_permission ON users.[grant] (permission_id);
CREATE INDEX ix_grant_scope ON users.[grant] (scope_id);
GO

-- One append-only table with every change except inserts.
-- payload holds the changed fields ({before, after}) or the changed links ({added, removed}).
-- No password data is ever stored here.
CREATE TABLE users.audit_log (
  audit_log_id   bigint IDENTITY NOT NULL,
  company_id     uniqueidentifier NULL,
  entity_type    nvarchar(30) NOT NULL,
  entity_id      uniqueidentifier NOT NULL,
  event_type     nvarchar(40) NOT NULL,
  actor_user_id  uniqueidentifier NULL,
  source         nvarchar(10) NOT NULL,
  payload        nvarchar(max) NOT NULL CONSTRAINT df_audit_log_payload DEFAULT N'{}',
  created_date   datetime2 NOT NULL CONSTRAINT df_audit_log_created DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_audit_log PRIMARY KEY (audit_log_id),
  CONSTRAINT ck_audit_log_payload CHECK (ISJSON(payload) = 1)
);

CREATE INDEX ix_audit_log_created ON users.audit_log (created_date DESC);
CREATE INDEX ix_audit_log_entity ON users.audit_log (entity_type, entity_id, audit_log_id DESC);
CREATE INDEX ix_audit_log_actor ON users.audit_log (actor_user_id);
CREATE INDEX ix_audit_log_company ON users.audit_log (company_id);
GO

-- Applications that sign users in through oum (OpenID Connect clients).
-- id is the oum row id (audited like every other entity); client_id is the string the app uses.
-- secret_hash is a SHA-256 hex digest: client secrets are long random strings, not passwords.
-- Same lifecycle as the other entities: active + deleted_at, permanent removal only after deactivation.
CREATE TABLE users.oidc_client (
  id                         uniqueidentifier NOT NULL,
  company_id                 uniqueidentifier NOT NULL,
  client_id                  nvarchar(100) NOT NULL,
  secret_hash                nvarchar(128) NOT NULL,
  name                       nvarchar(max) NOT NULL,
  redirect_uris              nvarchar(max) NOT NULL CONSTRAINT df_oidc_client_redirect DEFAULT N'[]',
  post_logout_redirect_uris  nvarchar(max) NOT NULL CONSTRAINT df_oidc_client_logout DEFAULT N'[]',
  token_scopes               nvarchar(max) NOT NULL CONSTRAINT df_oidc_client_scopes DEFAULT N'["openid","profile","email"]',
  grant_types                nvarchar(max) NOT NULL CONSTRAINT df_oidc_client_grants DEFAULT N'["authorization_code","refresh_token"]',
  active                     bit NOT NULL CONSTRAINT df_oidc_client_active DEFAULT 1,
  deleted_at                 datetime2 NULL,
  created_at                 datetime2 NOT NULL CONSTRAINT df_oidc_client_created DEFAULT SYSUTCDATETIME(),
  updated_at                 datetime2 NOT NULL CONSTRAINT df_oidc_client_updated DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_oidc_client PRIMARY KEY (id),
  CONSTRAINT fk_oidc_client_company FOREIGN KEY (company_id) REFERENCES users.company (id),
  CONSTRAINT ck_oidc_client_redirect CHECK (ISJSON(redirect_uris) = 1),
  CONSTRAINT ck_oidc_client_logout CHECK (ISJSON(post_logout_redirect_uris) = 1),
  CONSTRAINT ck_oidc_client_scopes CHECK (ISJSON(token_scopes) = 1),
  CONSTRAINT ck_oidc_client_grants CHECK (ISJSON(grant_types) = 1)
);
CREATE UNIQUE INDEX ux_oidc_client_id ON users.oidc_client (client_id) WHERE deleted_at IS NULL;
CREATE INDEX ix_oidc_client_company ON users.oidc_client (company_id);
GO

-- Everything the OpenID provider stores (sessions, grants, codes, tokens, interactions), one row each.
-- model is the library's model name; user_id (no foreign key) lets one statement revoke a user.
CREATE TABLE users.oidc_payload (
  model        nvarchar(50) NOT NULL,
  id           nvarchar(128) NOT NULL,
  payload      nvarchar(max) NOT NULL,
  grant_id     nvarchar(128) NULL,
  uid          nvarchar(128) NULL,
  user_code    nvarchar(128) NULL,
  user_id      uniqueidentifier NULL,
  expires_at   datetime2 NULL,
  consumed_at  datetime2 NULL,
  CONSTRAINT pk_oidc_payload PRIMARY KEY (model, id),
  CONSTRAINT ck_oidc_payload_payload CHECK (ISJSON(payload) = 1)
);
CREATE INDEX ix_oidc_payload_uid ON users.oidc_payload (model, uid);
CREATE INDEX ix_oidc_payload_grant ON users.oidc_payload (model, grant_id);
CREATE INDEX ix_oidc_payload_user_code ON users.oidc_payload (model, user_code);
CREATE INDEX ix_oidc_payload_user ON users.oidc_payload (user_id);
CREATE INDEX ix_oidc_payload_expires ON users.oidc_payload (expires_at);
GO

-- Two-step verification (TOTP). One row per enrolled user; deleting it resets the user.
-- secret_enc is the shared secret encrypted with TOTP_ENCRYPTION_KEY (AES-256-GCM, never plain text).
-- confirmed_at is null until the user proved the first code. last_step is the newest 30 s step accepted,
-- so a code cannot be used twice. recovery_hashes holds SHA-256 digests of the single-use recovery codes.
CREATE TABLE users.user_totp (
  user_id          uniqueidentifier NOT NULL,
  secret_enc       nvarchar(max) NOT NULL,
  confirmed_at     datetime2 NULL,
  last_step        bigint NOT NULL CONSTRAINT df_user_totp_step DEFAULT 0,
  recovery_hashes  nvarchar(max) NOT NULL CONSTRAINT df_user_totp_recovery DEFAULT N'[]',
  created_at       datetime2 NOT NULL CONSTRAINT df_user_totp_created DEFAULT SYSUTCDATETIME(),
  CONSTRAINT pk_user_totp PRIMARY KEY (user_id),
  CONSTRAINT fk_user_totp_user FOREIGN KEY (user_id) REFERENCES users.[user] (id),
  CONSTRAINT ck_user_totp_recovery CHECK (ISJSON(recovery_hashes) = 1)
);
GO
